import {SEEDS,LEVELS,QUESTS,WATER_INTERVAL,WATER_MAX,freshState,levelOf,seedById,progressOf,tick,applyAction,validateSave,readStatus,accrueEnergy,IRRIGATION_COST,ORDERS,orderById,deliveryPlan} from './engine.mjs';
import {icon,hamster,plantArt,gardenScenery} from './art.mjs?v=20261107-garden';
import {ordersView,activeOrderHTML,orderNeeds} from './orders.mjs';
import {createGardenMusic} from './music.mjs?v=20261106-autoplay';
import {createGardenSounds} from './sounds.mjs?v=20261106-sounds';
import {createGardenLife} from './garden-life.mjs?v=20261107-garden';

const STORAGE='squeek-grove-save-v2',LANG='squeek-grove-language',API='https://api.squeekchain.com/v1/status';
let state,lang='zh',storageOK=true,loadWarning=false,migrated=false;
try{lang=localStorage.getItem(LANG)==='en'?'en':'zh';const raw=localStorage.getItem(STORAGE)||localStorage.getItem('squeek-grove-save-v1');const parsed=raw?JSON.parse(raw):null;migrated=parsed?.version===1;state=parsed?validateSave(parsed):freshState();}catch(e){state=freshState();loadWarning=true;}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let view='garden',selectedSeed='carrot',selectedPlot=null,live=null,liveError=null,lastSample=null,workRemainder=0,liveTimer,polling=false,toastTimer,saveTimer,postcardURL,pendingImport;
const t=(zh,en)=>lang==='zh'?zh:en;
const music=createGardenMusic(updateMusicControls);
const sounds=createGardenSounds(updateSoundControls);
const life=createGardenLife({getState:()=>state,getLanguage:()=>lang});
const nameOf=s=>lang==='zh'?s.zh:s.en;
const num=n=>new Intl.NumberFormat(lang==='zh'?'zh-CN':'en-US').format(n);
const secText=n=>n>=60?`${Math.floor(n/60)}m ${n%60}s`:`${n}s`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const remaining=p=>Math.max(0,Math.ceil((1-progressOf(p,Date.now()))*seedById(p.seed).duration));
function save(){
 try{localStorage.setItem(STORAGE,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}
 const label=document.querySelector('#save-label');if(label)label.textContent=storageOK?t('已保存到本机','Saved on this device'):t('存档未保存，请导出','Not saved · export a backup');
}
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
const musicIcon='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 18V5l12-2v13M9 9l12-2"/><ellipse cx="6" cy="18" rx="3" ry="2.5"/><ellipse cx="18" cy="16" rx="3" ry="2.5"/></svg>';
function musicLabel(){return !music.supported?t('此浏览器不支持音乐','Music unavailable'):music.enabled?(music.playing?t('暂停音乐','Pause music'):t('关闭音乐','Turn music off')):t('播放音乐','Play music');}
function musicButton(settingsButton=false){return `<button class="${settingsButton?'secondary-button':'icon-button'} music-toggle ${music.enabled?'is-playing':''}" data-action="music-toggle" aria-label="${musicLabel()}" aria-pressed="${music.enabled}" title="${musicLabel()}" ${!music.supported?'disabled':''}>${musicIcon}${settingsButton?`<span data-music-label>${musicLabel()}</span>`:''}</button>`;}
function musicSettings(){return `<section class="music-settings" aria-label="${t('背景音乐','Background music')}"><div class="music-settings-top"><div><h3>${t('花园小调','A Little Sunny Garden')}</h3><p>${t('轻柔的循环旋律，陪你慢慢种植。','A gentle little melody to grow along with.')}</p></div>${musicButton(true)}</div><div class="music-volume-row"><label for="music-volume">${t('音乐音量','Music volume')}</label><input id="music-volume" type="range" min="0" max="100" step="1" value="${music.volume}" aria-valuetext="${music.volume}%"><output id="music-volume-value" for="music-volume">${music.volume}%</output></div><p class="music-hint">${t('进入花园自动播放；若暂时无声，点一下页面即可。','Music starts on entry. If it is silent, tap anywhere to begin.')}</p></section>`;}
const soundIcon='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/></svg>';
function soundLabel(){return !sounds.supported?t('此浏览器不支持音效','Sounds unavailable'):sounds.enabled?t('关闭音效','Turn sounds off'):t('开启音效','Turn sounds on');}
function soundSettings(){return `<section class="music-settings sound-settings" aria-label="${t('操作音效','Game sounds')}"><div class="music-settings-top"><div><h3>${t('花园的声音','Little garden sounds')}</h3><p>${t('播种、浇水、收获，各有一点小回应。','Little sounds for planting, watering and gathering.')}</p></div><button class="secondary-button music-toggle ${sounds.enabled?'is-playing':''}" data-action="sound-toggle" aria-label="${soundLabel()}" aria-pressed="${sounds.enabled}" ${!sounds.supported?'disabled':''}>${soundIcon}<span data-sound-label>${soundLabel()}</span></button></div><div class="music-volume-row"><label for="sound-volume">${t('音效音量','Sound volume')}</label><input id="sound-volume" type="range" min="0" max="100" step="1" value="${sounds.volume}" aria-valuetext="${sounds.volume}%"><output id="sound-volume-value" for="sound-volume">${sounds.volume}%</output></div><div class="sound-settings-bottom"><p class="music-hint">${t('可单独关闭；记住音效开关和音量。','Independent of music; remembers your settings.')}</p><button class="secondary-button sound-preview" data-action="sound-preview" ${!sounds.supported||!sounds.enabled||!sounds.volume?'disabled':''}>${t('试听音效','Try a sound')}</button></div></section>`;}
function updateSoundControls(){
 document.querySelectorAll('[data-action="sound-toggle"]').forEach(button=>{button.setAttribute('aria-pressed',String(sounds.enabled));button.setAttribute('aria-label',soundLabel());button.classList.toggle('is-playing',sounds.enabled);button.querySelector('[data-sound-label]').textContent=soundLabel();});
 const slider=document.querySelector('#sound-volume');if(slider){slider.value=sounds.volume;slider.setAttribute('aria-valuetext',sounds.volume+'%');}
 const output=document.querySelector('#sound-volume-value');if(output)output.textContent=sounds.volume+'%';
 const preview=document.querySelector('[data-action="sound-preview"]');if(preview)preview.disabled=!sounds.supported||!sounds.enabled||!sounds.volume;
}
function updateMusicControls(){
 document.querySelectorAll('[data-action="music-toggle"]').forEach(button=>{button.setAttribute('aria-pressed',String(music.enabled));button.setAttribute('aria-label',musicLabel());button.title=musicLabel();button.disabled=!music.supported;button.classList.toggle('is-playing',music.enabled);const label=button.querySelector('[data-music-label]');if(label)label.textContent=musicLabel();});
 const slider=document.querySelector('#music-volume');if(slider){slider.value=music.volume;slider.setAttribute('aria-valuetext',music.volume+'%');}
 const output=document.querySelector('#music-volume-value');if(output)output.textContent=music.volume+'%';
}
function header(){return `<header class="header"><a href="#garden" class="brand" data-action="nav" data-view="garden" aria-label="Squeek Grove"><span class="brand-mark">${hamster()}</span><span><span class="brand-name">Squeek Grove</span><span class="brand-sub" style="display:block">${t('仓 鼠 花 园','A LITTLE WORLD, GROWING')}</span></span></a><nav class="nav" aria-label="${t('主导航','Main navigation')}">${[['garden','garden','我的花园','Garden'],['orders','book','订单仓库','Orders'],['collection','book','种子图鉴','Seed journal'],['achievements','star','成长足迹','Milestones']].map(([key,ico,zh,en])=>`<button data-action="nav" data-view="${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(ico,17)}<span>${t(zh,en)}</span></button>`).join('')}</nav><div class="header-actions">${musicButton()}<button class="quiet-button" data-action="help" aria-label="${t('玩法说明','How to play')}">${icon('help',18)}<span>${t('怎么玩','How to play')}</span></button><button class="quiet-button lang-button" data-action="language" aria-label="${t('Switch to English','切换为中文')}">${t('EN','中文')}</button><button class="icon-button" data-action="settings" aria-label="${t('存档与设置','Save and settings')}">${icon('settings',16)}</button></div></header>`;}
function resources(){return `<div class="resource-bar" aria-label="${t('花园资源','Garden resources')}"><div class="resource seed"><div class="resource-top">${icon('seed',19)}<b id="coins">${num(state.coins)}</b></div><div class="resource-label">${t('种子币','Seed coins')}</div></div><div class="resource water"><div class="resource-top">${icon('water',19)}<b id="water">${state.water}<small style="font-size:11px;letter-spacing:0;opacity:.6"> / ${WATER_MAX}</small></b></div><div class="resource-label" id="water-label">${t('清晨露水','Morning dew')}</div></div><div class="resource energy"><div class="resource-top">${icon('bolt',19)}<b id="energy">${state.energy}</b></div><div class="resource-label">${t('跑轮能量','Wheel energy')}</div></div></div>`;}
function render(){
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';
 const titles={orders:t('这一篮收成，你来安排。','A harvest worth planning.'),garden:t('种下一点，慢慢长大。','Small seeds. Little wonders.'),collection:t('把每一次收获，珍藏起来。','A journal of little discoveries.'),achievements:t('小花园，也有大成长。','Every little step counts.')};
 const subtitles={orders:t('先接订单，安排土地与灌溉。把每一份收成用在合适的地方。','Choose a delivery, plan your plots and decide where your wheel energy goes.'),garden:t('蓄下跑轮能量，选择灌溉地块，为下一份订单安排收成。','Bank wheel energy, choose a plot to irrigate and grow your next delivery.'),collection:t('从第一颗种子，到一座四季生长的花园。','From your very first seed to a garden full of life.'),achievements:t('记录每一份用心，解锁花园里的新风景。','Celebrate your harvests and make this little world your own.')};
 app.innerHTML=`<div class="shell">${header()}<main id="main" class="main"><section class="intro"><div><div class="eyebrow">${view==='garden'?'YOUR LITTLE CORNER OF SQUEEKCHAIN':view==='collection'?'THE SEED JOURNAL':view==='orders'?'THE HARVEST EXCHANGE':'A GARDENER’S JOURNEY'}</div><h1>${titles[view]}</h1><p>${subtitles[view]}</p></div>${resources()}</section><div id="view-content">${view==='garden'?gardenView():view==='collection'?collectionView():view==='orders'?ordersView(state,lang):achievementsView()}</div><footer class="footer"><span class="footer-left">${icon('sprout',14)} Squeek Grove · ${t('独立社区作品，由沐光打造','An independent community garden by Muguang')}</span><span class="footer-links"><span>${t('游戏资源无链上价值','Game resources have no onchain value')}</span><a href="https://squeekchain.com" target="_blank" rel="noopener noreferrer">Squeekchain ${icon('external',10)}</a><button data-action="about" style="font-size:inherit;padding:0;color:inherit">${t('关于花园','About')}</button></span></footer></main></div>`;
 if(view==='garden'){renderPlots();renderFocus();renderLive();life.update();}updateStats();
}
function gardenView(){return `<div class="game-layout"><div class="garden-column"><section class="garden-card" aria-label="${t('互动种植区','Interactive garden')}"><div class="garden-toolbar"><div class="garden-title">${icon('sprout',18)}<h2>${t('沐光的小花园','Muguang’s little garden')}</h2><span class="level-pill" id="level-label">LV. ${levelOf(state.xp)}</span></div><div class="toolbar-right"><span class="save-state">${icon('check',12)}<span id="save-label">${t('已保存到本机','Saved on this device')}</span></span><button class="small-button" data-action="share">${icon('share',13)}${t('花园明信片','Postcard')}</button></div></div>${life.controls()}<div class="garden-world">${gardenScenery()}${life.ambient()}<div class="world-sign">${icon('sprout',12)} ${t('每一点用心，都会长大','LITTLE BY LITTLE, WE GROW')}</div><div class="world-weather"><span class="scene-phase-dot" aria-hidden="true"></span><span><b id="scene-label"></b><small id="scene-clock"></small></span></div><div class="plot-grid" role="group" aria-label="${t('九块种植地','Nine garden plots')}">${state.plots.map((p,i)=>`<button class="plot" data-action="plot" data-index="${i}" id="plot-${i}"></button>`).join('')}</div><div id="garden-decor">${decorArt()}</div>${life.basket()}${life.companion()}</div><div id="focus-panel" class="focus-panel"></div><div class="garden-bottom"><span>${icon('leaf',14)}<span id="garden-tip">${t('你的第一份收获，正在路上','Your first little harvest is on its way')}</span></span><button data-action="harvest-all">${t('收获成熟植物','Harvest ready crops')} ${icon('arrow',13)}</button></div></section><section class="seed-section"><div class="section-head"><h2>${icon('seed',16)}${t('挑一颗种子','Pick a little seed')}</h2><span>${t('先选种子，再点击空地播种','Choose a seed, then an empty plot')}</span></div><div class="seed-list">${SEEDS.map((s,i)=>seedCard(s,i)).join('')}</div></section><div class="garden-next-step"><span>${icon('seed',16)}${t('收成会先进入仓库。可以卖出，也可以留着交单。','Your harvest goes into storage. Sell it or save it for an order.')}</span><button class="secondary-button" data-action="nav" data-view="orders">${t('打开仓库','Open warehouse')} ${icon('arrow',13)}</button></div></div><aside class="sidebar"><section class="side-card live-card"><div class="side-heading"><h2>SQUEEKTOSHI LIVE</h2><span class="status-pill" id="live-status"><span class="status-dot offline"></span>${t('连接中','Connecting')}</span></div><div class="wheel-scene" id="wheel-scene"><div class="wheel"><div class="wheel-spokes">${icon('wheel',98)}</div></div>${hamster('mini-hamster')}<div class="wheel-stand"></div></div><h3 class="live-title" id="live-title">${t('听听跑轮的声音','Listening to the wheel')}</h3><p class="live-subtitle" id="live-subtitle">${t('正在连接 Squeekchain 公开数据','Connecting to Squeekchain’s public data')}</p><div class="live-stats"><div>${t('跑轮转速','Wheel speed')}<strong id="rpm">— <small>RPM</small></strong></div><div>${t('已结算区块','Settled blocks')}<strong id="block-height">—</strong></div></div><div class="energy-reservoir"><span>${t('已储存的跑轮能量','Stored wheel energy')}</span><b id="reservoir-value">${state.energy} / 100</b><div class="progress-track"><div class="progress-fill" id="reservoir-fill" style="width:${state.energy}%"></div></div><small id="irrigation-target">${t('先点击一株生长中的植物','Select a growing plant first')}</small></div><button class="primary-button full-width" data-action="irrigate-selected" id="irrigate-selected" disabled>${icon('water',15)}${t('灌溉选中地块','Irrigate selected plot')} <span>· 4</span></button><p class="live-foot" id="live-foot">${t('它在奔跑，你的花园就积攒能量','When the wheel moves, your garden gathers energy')}</p><button class="energy-log-link" data-action="energy-log">${t('能量从哪里来','Where energy comes from')} ${icon('arrow',11)}</button></section><section class="side-card current-order-card"><div class="side-heading"><h2>${t('收成订单','Harvest order')}</h2>${icon('book',16)}</div><div id="active-order">${activeOrderHTML(state,lang,true)}</div></section><div class="garden-note">${icon('leaf',18)}<p>${t('不用连接钱包。进度保存在当前浏览器，记得偶尔导出一份存档。','No wallet needed. Progress stays in this browser. Export a backup from time to time.')}</p></div></aside></div>`;}
function seedCard(s,i){const locked=levelOf(state.xp)<s.level;return `<button class="seed-card ${selectedSeed===s.id?'selected':''} ${locked?'is-locked':''}" data-action="seed" data-seed="${s.id}" aria-label="${nameOf(s)}, ${s.cost} ${t('种子币','seed coins')}${locked?', '+t('需要等级','Requires level')+' '+s.level:''}" aria-pressed="${selectedSeed===s.id}"><span class="seed-number">SEED / 0${i+1}</span><span class="seed-thumb">${plantArt(s.id)}</span><div class="seed-name">${nameOf(s)}</div><div class="seed-bottom"><span class="seed-price">${locked?icon('lock',11):icon('seed',11)}${locked?'LV. '+s.level:s.cost}</span><span>${secText(s.duration)}</span></div></button>`;}
function decorArt(){if(state.decor==='mushroom')return `<svg class="decor-mushroom" width="58" height="58" viewBox="0 0 58 58" aria-hidden="true"><path d="M22 22h14v31H22Z" fill="#ede2bb"/><path d="M6 27c0-31 46-31 46 0Z" fill="#c58d68"/><g fill="#f0dec2"><circle cx="20" cy="15" r="4"/><circle cx="36" cy="12" r="4"/><circle cx="41" cy="22" r="3"/></g><ellipse cx="29" cy="53" rx="18" ry="4" fill="#829a6740"/></svg>`;if(state.decor==='lantern')return `<svg class="decor-lantern" width="58" height="75" viewBox="0 0 58 75" aria-hidden="true"><path d="M13 70V8q0-8 18-4v12" stroke="#788565" stroke-width="4" fill="none"/><rect x="21" y="16" width="22" height="30" rx="4" fill="#eee0a1" stroke="#9a9f73" stroke-width="3"/><path d="M32 17v29M20 30h24" stroke="#bdba7e" stroke-width="2"/><circle cx="32" cy="31" r="6" fill="#fff6c5"/><path d="M6 70h17" stroke="#788565" stroke-width="5" stroke-linecap="round"/></svg>`;return '';}
function renderPlots(){const now=Date.now();state.plots.forEach((p,i)=>{
 const el=document.querySelector('#plot-'+i);if(!el)return;
 const progress=p.plant?progressOf(p.plant,now):0,ready=progress>=1;
 el.className=`plot ${!p.unlocked?'locked':!p.plant?'empty':'planted'} ${selectedPlot===i?'selected':''} ${p.plant?.wheelTended?'wheel-grown':''} ${ready?'crop-ready':''}`;
 el.dataset.watered=String(Boolean(p.plant?.watered));
 const stage=progress<.12?-1:progress<.32?0:progress<.72?1:2;
 const visualKey=JSON.stringify([p.unlocked,p.plant?.seed,stage,ready,p.plant?.wheelTended,selectedSeed,lang]);
 let html,label,plotLabel;
 if(!p.unlocked){html=`<span class="plot-icon">${icon('lock',16)}</span><span class="plot-label">${t('开垦土地','Expand')}</span>`;label=t(`第 ${i+1} 块地，未开垦`,`Plot ${i+1}, locked`);}
 else if(!p.plant){html=`<span class="plot-icon">${icon('plus',21)}</span><span class="plot-label">${t('种下一颗','Plant a seed')}</span>`;label=t(`第 ${i+1} 块空地，播种${nameOf(seedById(selectedSeed))}`,`Empty plot ${i+1}, plant ${nameOf(seedById(selectedSeed))}`);}
 else{const seed=seedById(p.plant.seed);plotLabel=ready?nameOf(seed):secText(remaining(p.plant));html=`<span class="plant-visual" data-stage="${stage}">${plantArt(seed.id,progress)}</span><span class="plot-label">${plotLabel}</span>${ready?`<span class="ready-bubble">${t('可收获','Ready!')}</span>`:p.plant.wheelTended?`<span class="wheel-crop-badge">${icon('bolt',10)} ${t('跑轮作物','Wheel-grown')}</span>`:''}`;label=`${t('第','Plot ')} ${i+1} · ${nameOf(seed)} · ${ready?t('点击收获','Ready to harvest'):t('剩余','Remaining ')+plotLabel}`;}
 if(el.dataset.visualKey!==visualKey){el.innerHTML=html;el.dataset.visualKey=visualKey;}else if(plotLabel){const label=el.querySelector('.plot-label');if(label.textContent!==plotLabel)label.textContent=plotLabel;}
 el.setAttribute('aria-label',label);el.setAttribute('aria-pressed',selectedPlot===i?'true':'false');
 });}
function renderFocus(){
 const el=document.querySelector('#focus-panel');if(!el)return;
 const p=selectedPlot!==null?state.plots[selectedPlot]:null,ready=p?.plant&&progressOf(p.plant,Date.now())>=1;
 const detail=p?.plant?(ready?t('收获后进入仓库，可出售或交付订单。','Harvest into storage, then sell or use in a delivery.'):t(`还需 ${secText(remaining(p.plant))} · ${p.plant.wheelTended?'已用跑轮能量培育':'选择露水或跑轮灌溉'}`,`Ready in ${secText(remaining(p.plant))} · ${p.plant.wheelTended?'Wheel-grown crop':'Choose dew or wheel irrigation'}`)):'';
 const key=JSON.stringify([selectedPlot,p?.unlocked,p?.plant?.seed,p?.plant?.watered,p?.plant?.wheelTended,ready,state.water>0,state.energy>=IRRIGATION_COST,state.coins,lang]);
 if(el.dataset.focusKey===key){const copy=el.querySelector('.focus-copy p');if(copy&&p?.plant)copy.textContent=detail;return;}el.dataset.focusKey=key;
 if(!p){el.innerHTML=`<div class="panel-empty">${icon('sprout',20)}<span>${t('选中一株植物，决定用露水浇灌，还是分配跑轮能量。','Select a growing plant to allocate dew or stored wheel energy.')}</span></div>`;return;}
 if(!p.unlocked){const cost=30+(state.plots.filter(p=>p.unlocked).length-3)*15;el.innerHTML=`<div class="focus-copy"><h3>${t('给下一笔订单，多一块土地','One more plot for your next order')}</h3><p>${t('永久解锁后，可以种植任意已开放种子。','Permanently unlock this plot for any available seed.')}</p></div><div class="focus-actions"><button class="primary-button" data-action="unlock" data-index="${selectedPlot}" ${state.coins<cost?'disabled':''}>${icon('plus',13)}${t('开垦','Unlock')} · ${cost}</button></div>`;return;}
 if(!p.plant){el.innerHTML=`<div class="focus-copy"><h3>${t('下一株，种什么？','What will you plant next?')}</h3><p>${t('先看看订单需要什么，选好种子，再点击这块地。','Check your order, choose a seed, then tap this plot.')}</p></div><button class="secondary-button" data-action="nav" data-view="orders">${t('查看订单','View orders')}</button>`;return;}
 const seed=seedById(p.plant.seed);
 el.innerHTML=`<div class="focus-plant">${plantArt(seed.id,progressOf(p.plant,Date.now()),50)}</div><div class="focus-copy"><h3>${nameOf(seed)} <span class="crop-quality">${p.plant.wheelTended?t('跑轮作物','Wheel-grown'):t('普通作物','Regular')}</span></h3><p>${detail}</p></div><div class="focus-actions">${ready?`<button class="primary-button" data-action="harvest" data-index="${selectedPlot}">${t('收获入仓','Harvest')}</button>`:`<button class="secondary-button" data-action="water" data-index="${selectedPlot}" ${p.plant.watered||!state.water?'disabled':''}>${icon('water',13)}${p.plant.watered?t('已浇露水','Watered'):t('露水 · 1','Dew · 1')}</button><button class="primary-button" data-action="irrigate" data-index="${selectedPlot}" ${p.plant.wheelTended||state.energy<IRRIGATION_COST?'disabled':''}>${icon('bolt',13)}${p.plant.wheelTended?t('已用跑轮能量','Irrigated'):t('跑轮 · 4','Wheel · 4')}</button>`}</div>`;
}
function questsHTML(){return QUESTS.map(q=>{const count=Math.min(q.goal,state.stats[q.field]),complete=count>=q.goal,claimed=state.claimed.includes(q.id);return `<div class="quest-row"><div class="quest-title-row"><h3 class="quest-title">${icon(claimed?'check':'sprout',13)}${nameOf(q)}</h3><span class="quest-count">${count}/${q.goal}</span></div><p class="quest-hint">${t(q.hint,q.enHint)}</p><div class="progress-track"><div class="progress-fill" style="width:${count/q.goal*100}%"></div></div><div class="quest-reward"><span>+${q.reward} ${t('种子币','seed coins')}</span>${claimed?`<span>${t('已领取','Collected')}</span>`:complete?`<button class="claim-button" data-action="claim" data-id="${q.id}">${t('领取奖励','Collect')}</button>`:''}</div></div>`;}).join('');}
function collectionView(){return `<section class="view-panel"><p class="collection-intro">${t('四种种子，四种不同的等待。每次收获都会留下记录；积累经验后，新的植物会为你开放。','Four kinds of seeds, each with its own rhythm. Every harvest is remembered. Earn experience to discover new plants.')}</p><div class="collection-grid">${SEEDS.map((s,i)=>`<article class="collection-card"><div class="collection-art" style="background:${['#e8eddb','#f2eedc','#e8e6ef','#efead5'][i]}"><span class="collection-index">SPECIMEN / 0${i+1}</span>${plantArt(s.id)}</div><div class="collection-copy"><h2>${nameOf(s)}</h2><p>${t(s.subtitle,['A sweet, simple first harvest.','A little sunshine in the soil.','Good things come to those who wait.','Always looking toward the light.'][i])}</p><div class="collection-meta"><span>${secText(s.duration)}</span><span>${t('成本','Cost')} ${s.cost} / ${t('普通售价','Sale')} ${s.reward}</span></div><span class="collection-badge">${icon(state.collection[s.id]?'check':'sprout',12)}${state.collection[s.id]?t(`已收获 ${state.collection[s.id]} 株`,`${state.collection[s.id]} harvested`):levelOf(state.xp)<s.level?t(`花园 Lv.${s.level} 解锁`,`Unlocks at garden Lv.${s.level}`):t('等待你的第一份收获','Awaiting your first harvest')}</span><button class="secondary-button full-width" style="margin-top:16px" data-action="seed-detail" data-seed="${s.id}">${t('查看种植笔记','Growing notes')}</button></div></article>`).join('')}</div></section>`;}
function achievementsView(){const lv=levelOf(state.xp),threshold=LEVELS[lv]||state.xp,previous=LEVELS[lv-1],progress=lv===6?100:Math.min(100,(state.xp-previous)/(threshold-previous)*100);const list=[['seed',t('第一颗果实','The first harvest'),t('收获第一株植物','Harvest your first plant'),state.stats.harvested>=1],['water',t('露水收藏家','Dew collector'),t('累计浇水 10 次','Water plants 10 times'),state.stats.watered>=10],['garden',t('花园扩建师','Room to bloom'),t('开垦 6 块土地','Unlock 6 garden plots'),state.plots.filter(p=>p.unlocked).length>=6],['book',t('植物收藏家','Plant collector'),t('收获全部 4 种植物','Harvest all 4 plant species'),SEEDS.every(s=>state.collection[s.id]>0)],['bolt',t('与仓鼠同频','In step with Squeektoshi'),t('用跑轮能量灌溉一株植物','Irrigate a plant with wheel energy'),state.stats.boosted>0],['book',t('准时送达','Right on time'),t('完成 3 笔收成订单','Complete 3 harvest orders'),state.stats.delivered>=3],['star',t('小小丰收节','A little harvest festival'),t('累计收获 30 株植物','Harvest 30 plants'),state.stats.harvested>=30]];return `<section class="view-panel"><div class="xp-banner"><strong>Lv. ${lv}</strong><div class="xp-copy"><h2>${t('你的园丁等级','Your gardener level')}</h2><div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div><p>${state.xp} XP ${lv===6?'· '+t('已满级，继续自在种植吧','Maximum level. Keep growing!'):'/ '+threshold+' XP · '+t('收获植物积累经验','Harvest plants to earn experience')}</p></div>${icon('sprout',35)}</div><div class="achievement-grid">${list.map(([ico,title,description,earned])=>`<article class="achievement-card ${earned?'earned':''}"><div class="achievement-medal">${icon(ico,25)}</div><div><h2>${title}</h2><p>${description}</p><div class="achievement-status">${earned?'✓ '+t('已达成','Achieved'):t('慢慢来，终会到达','A little more growing to do')}</div></div></article>`).join('')}</div><h2 class="subhead">${t('花园的新风景','Make it your own')}</h2><div class="decor-list">${[['natural','leaf',t('自然原野','Natural meadow'),t('默认花园布置','Your original garden'),true],['mushroom','sprout',t('蘑菇小角落','Mushroom corner'),t('收获 3 株植物解锁','Unlock after 3 harvests'),state.stats.harvested>=3],['lantern','sun',t('一盏小灯','A little lantern'),t('园丁 Lv.3 解锁','Unlock at garden Lv.3'),lv>=3]].map(([id,ico,title,hint,available])=>`<button class="decor-choice ${state.decor===id?'active':''}" data-action="decor" data-id="${id}" ${!available?'disabled':''}><span class="decor-icon">${icon(ico,30)}</span><span><b>${title} ${state.decor===id?'✓':''}</b><p>${hint}</p></span></button>`).join('')}</div><h2 class="subhead">${t('花园小目标','Little garden goals')}</h2><div class="goals-grid">${questsHTML()}</div></section>`;}
function updateStats(){
 const orderBefore=state.activeOrder?.sequence;tick(state);
 const set=(id,value)=>{const el=document.getElementById(id);if(el&&el.textContent!==String(value))el.textContent=value;};
 set('coins',num(state.coins));set('energy',state.energy);set('reservoir-value',`${state.energy} / 100`);set('strategy-energy-value',`${state.energy} / 100`);
 const fill=document.getElementById('reservoir-fill');if(fill)fill.style.width=state.energy+'%';
 const water=document.getElementById('water');if(water&&water.dataset.value!==String(state.water)){water.innerHTML=`${state.water}<small style="font-size:11px;letter-spacing:0;opacity:.6"> / ${WATER_MAX}</small>`;water.dataset.value=state.water;}
 const refill=Math.max(1,Math.ceil((WATER_INTERVAL-(Date.now()-state.waterAt))/1000));set('water-label',state.water<WATER_MAX?t(`露水 · ${refill}s 后补充`,`Dew · +1 in ${refill}s`):t('露水已满','Dew is full'));set('level-label','LV. '+levelOf(state.xp));
 const count=state.plots.filter(p=>p.plant&&progressOf(p.plant,Date.now())>=1).length;set('garden-tip',count?t(`${count} 株已成熟，收获后可入仓交单`,`${count} crops ready for storage and deliveries`):t('照料植物，也为下一份订单留点空间','Tend your plants and plan your next delivery'));
 const target=selectedPlot===null?null:state.plots[selectedPlot]?.plant;
 const irrigate=document.getElementById('irrigate-selected');if(irrigate)irrigate.disabled=!target||target.wheelTended||progressOf(target,Date.now())>=1||state.energy<IRRIGATION_COST;
 set('irrigation-target',!target?t('先点击一株生长中的植物','Select a growing plant first'):target.wheelTended?t(`地块 ${selectedPlot+1} 已用跑轮能量`,`Plot ${selectedPlot+1} already irrigated`):progressOf(target,Date.now())>=1?t('已成熟，请先收获再种植','Ready to harvest; plant a new crop next'):t(`目标：地块 ${selectedPlot+1} · ${nameOf(seedById(target.seed))}`,`Target: plot ${selectedPlot+1} · ${nameOf(seedById(target.seed))}`));
 if(orderBefore&&!state.activeOrder){save();const box=document.getElementById('active-order');if(box)box.innerHTML=activeOrderHTML(state,lang,view==='garden');if(view==='orders')document.querySelectorAll('[data-action="accept-order-preview"]').forEach(button=>{button.disabled=levelOf(state.xp)<orderById(button.dataset.id).level;button.textContent=button.disabled?'Lv. '+orderById(button.dataset.id).level:t('接这单','Accept');});toast(t('订单已超时。作物都保留，可以重新安排。','Order expired. Your crops are safe; choose a new delivery.'));}
 if(state.activeOrder){const seconds=Math.max(0,Math.ceil((state.activeOrder.expiresAt-Date.now())/1000));document.querySelectorAll('[data-order-countdown]').forEach(e=>{e.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;e.classList.toggle('urgent',seconds<=30);});}
 if(!storageOK)set('save-label',t('未保存，请导出','Not saved · export'));
}
function liveUsable(){return live&&!liveError&&live.fresh&&Date.now()-live.fetchedAt<=90000;}
function renderLive(){if(view!=='garden')return;const usable=liveUsable(),running=usable&&live.core==='ACTIVE'&&live.rpm>0&&live.hardware,fault=usable&&live.core==='COUNTER_FAULT';const set=(id,txt)=>{const e=document.getElementById(id);if(e)e.textContent=txt;};const pill=document.getElementById('live-status');if(pill)pill.innerHTML=`<span class="status-dot ${!usable||fault?'offline':''}"></span>${usable?(live.hardware?t('真实数据','Live data'):t('非硬件数据','Non-hardware')):liveError||live?t('连接中断','Unavailable'):t('连接中','Connecting')}`;set('live-title',!usable?t('等一等跑轮的消息','Waiting for the wheel'):fault?t('跑轮读数异常','Wheel reading fault'):!live.hardware?t('非硬件数据源','Non-hardware data'):running?t('Squeektoshi 在奔跑','Squeektoshi is running'):t('跑轮暂时没有活动','The wheel is quiet'));set('live-subtitle',!usable?t('暂时无法获取新读数，种植和浇水照常继续。','No fresh readings right now. Planting and watering still work.'):fault?t('暂停积攒能量，等待设备恢复。','Energy collection pauses until readings recover.'):running?t('真实跑轮新增的工作量，正在为花园蓄能。','New work from the real wheel adds energy to your garden.'):!live.hardware?t('仅显示读数，不产生真实跑轮能量。','Readings are visible but do not earn live wheel energy.'):t('等它再跑起来时，你的花园就能积攒能量。','Energy will accumulate when the wheel starts moving again.'));set('rpm',usable&&!fault?live.rpm.toFixed(1)+' RPM':'— RPM');set('block-height',usable&&live.height&&/^\d+$/.test(live.height)?num(BigInt(live.height)):'—');const wheel=document.getElementById('wheel-scene');if(wheel)wheel.classList.toggle('running',!!running);const foot=document.getElementById('live-foot');if(foot)foot.innerHTML=usable?t('单株成长 +35% · 培育订单需要的跑轮作物','+35% growth · cultivates wheel-grown crops for orders'):`<button data-action="reconnect" style="font:inherit;color:inherit;padding:0;text-decoration:underline">${t('重新连接','Reconnect')}</button> · ${t('不使用模拟读数','No simulated readings')}`;}
async function poll(){
 if(polling)return;clearTimeout(liveTimer);if(document.hidden){liveTimer=setTimeout(poll,30000);return;}
 polling=true;let wait=15000;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);
 try{
  const response=await fetch(API,{signal:controller.signal,headers:{Accept:'application/json'}});
  if(!response.ok){if(response.status===429)wait=Math.max(30000,(Number(response.headers.get('Retry-After'))||60)*1000);throw Error('http_'+response.status);}
  const next=readStatus(await response.json()),result=accrueEnergy(state,lastSample,next,workRemainder);workRemainder=result.carry;if(result.added)save();lastSample=next;live=next;liveError=null;
 }catch(e){liveError=e.message;lastSample=null;workRemainder=0;wait=Math.max(wait,60000);}
 finally{clearTimeout(timeout);polling=false;renderLive();updateStats();liveTimer=setTimeout(poll,wait);}
}
function afterAction(){save();render();}
function perform(action){
 const origin=Number.isInteger(action.index)?life.capture(action.index):null,visualSeed=state.plots[action.index]?.plant?.seed||action.seed;
 const lv=levelOf(state.xp),result=applyAction(state,action);
 if(!result.ok){const messages={coins:t('种子币不够，可以去仓库卖出收成。','Not enough seed coins. Sell a crop from your warehouse.'),water:t('露水正在补充，稍等一会儿。','Dew is refilling. Give it a moment.'),watered:t('这株植物已经浇过露水。','This crop has already received dew.'),irrigated:t('这株已经用跑轮能量灌溉过了。','This crop has already received wheel irrigation.'),growing:t('请先选中一株还在生长的植物。','Select a plant that is still growing.'),level:t('收获或交付订单，升级后可以解锁。','Harvest or deliver orders to unlock this level.'),energy:t('需要 4 点已储存的跑轮能量，普通种植和订单仍可进行。','You need 4 stored wheel energy. Standard crops and orders are still available.'),stock:t('仓库数量不足，请先收获需要的植物。','Not enough stock. Harvest the required crops first.'),active_order:t('一次安排一笔订单，先完成或取消当前订单。','Complete or cancel your current order first.'),order_changed:t('这笔订单已过期或发生变化，请重新查看。','This order has expired or changed. Review it again.'),unready:t('还需要一点时间。','This crop needs a little more time.')};toast(messages[result.reason]||t('这一步暂时不可用。','This action is not available yet.'));save();render();return false;}
 const cue=levelOf(state.xp)>lv?'level':({'accept-order':'accept'}[action.type]||action.type);sounds.play(cue);
 if(action.type==='harvest'){toast(t(`${nameOf(seedById(result.seed))}已入仓 · +${result.xp} 经验。可以卖出或留着交单。`,`${nameOf(seedById(result.seed))} stored · +${result.xp} XP. Sell it or save it for an order.`));}
 else if(action.type==='plant')toast(t('种下啦。选中小苗，为它分配露水或跑轮能量。','Planted. Select the seedling to allocate dew or wheel energy.'));
 else if(action.type==='water')toast(t('露水浇灌完成，成长进度增加 25%。','Dew applied. Growth increased by 25%.'));
 else if(action.type==='unlock')toast(t('新土地已开垦，可以安排更多作物。','New plot unlocked. Room for more crops.'));
 else if(action.type==='irrigate')toast(t(`4 点能量送到地块 ${action.index+1}，成长 +35%，这株会成为跑轮作物。`,`4 energy allocated to plot ${action.index+1}. +35% growth and wheel-grown quality.`));
 else if(action.type==='sell')toast(t(`已卖出 1 份，获得 ${result.reward} 种子币。`,`Sold 1 crop for ${result.reward} seed coins.`));
 else if(action.type==='accept-order')toast(t('接单成功。现在开始计时，去安排种植吧。','Order accepted. The timer has started. Plan your crops.'));
 else if(action.type==='deliver')toast(t(`准时送达！+${result.reward} 种子币 · +${result.xp} 经验。`,`Delivered on time! +${result.reward} coins · +${result.xp} XP.`));
 else if(action.type==='cancel-order')toast(t('订单已取消，仓库和土地里的作物全部保留。','Order cancelled. All crops and stored harvests are safe.'));
 else if(action.type==='claim')toast(t('目标奖励已领取。','Goal reward collected.'));
 if(levelOf(state.xp)>lv)setTimeout(()=>toast(t(`园丁升到 Lv.${levelOf(state.xp)}，可以查看新种子和新订单。`,`Gardener Lv.${levelOf(state.xp)}! Explore new seeds and orders.`)),1800);
 afterAction();life.react(action.type);life.effect(action.type,action.index,origin,visualSeed);return true;
}
function openModal(title,body){modal.innerHTML=`<div class="modal-top"><h2 id="modal-title">${title}</h2><button class="modal-close" data-action="close" aria-label="${t('关闭','Close')}">${icon('close',16)}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function help(){openModal(t('一座小花园，怎么玩？','A little guide to your garden'),`<ol><li><b>${t('先看订单，再安排种植。','Pick an order and plan your crops.')}</b> ${t('订单仓库里可以接单，一次一单；确认后开始倒计时，关闭页面也会继续计时。','Accept one order at a time from the warehouse. Its timer starts after confirmation and continues while the page is closed.')}</li><li><b>${t('把灌溉分给需要的植物。','Choose which plants to irrigate.')}</b> ${t('露水增加 25% 成长；4 点跑轮能量增加 35%，并培育跑轮作物。每株两种灌溉各用一次，成熟后不能补做。','Dew adds 25% growth. Four wheel energy adds 35% and wheel-grown quality. Each can be used once before maturity.')}</li><li><b>${t('收获入仓，出售或交单。','Harvest into storage, then sell or deliver.')}</b> ${t('收获获得经验；出售或交付才得到种子币。跑轮作物售价为普通作物的 1.5 倍，取整。交付前可以核对扣除数量。','Harvesting earns XP. Sales and deliveries earn coins. Wheel-grown crops sell for 1.5× the regular price, rounded down. Review exact quantities before delivery.')}</li><li><b>${t('仓鼠停转，也能继续安排。','Keep planning while the wheel is quiet.')}</b> ${t('储能在停转或断线时仍能使用。普通种植照常进行。订单超时、取消都保留作物。露水每 45 秒恢复一滴，最多 6 滴。','Stored energy survives idle periods and disconnections. Ordinary plants keep growing. Expired or cancelled orders keep all crops. Dew refills every 45 seconds, up to six.')}</li></ol><div class="modal-note"><b>${t('能量来自真实新增读数','Energy comes from new hardware work')}</b><p>${t('页面可见时每 15 秒读取公开接口，同一计数周期内每新增 5 个硬件工作单位积攒 1 点能量，上限 100。首次连接、断线恢复、计数器重置、过期或非硬件读数不补发能量。','The visible page polls every 15 seconds. Five new hardware work units in the same epoch earn one energy, capped at 100. Initial connections, reconnects, resets, stale and non-hardware readings do not award catch-up energy.')}</p><p>${t('游戏资源、订单与记录都保存在本机，不是官方积分、链上凭证或奖励资格。','Resources, orders and records are local game data, not official points, onchain certificates or reward eligibility.')}</p></div><div class="modal-actions"><button class="primary-button" data-action="close">${t('开始安排我的花园','Plan my garden')}</button></div>`);}
function settings(){openModal(t('花园设置','Garden settings'),`${musicSettings()}${soundSettings()}<p>${t('进度自动保存在当前浏览器。换设备或清理浏览器前，请先导出存档。','Progress is saved in this browser. Export a backup before changing devices or clearing browser data.')}</p>${!storageOK?`<div class="modal-note">${t('浏览器当前无法写入存档。请使用下方导出按钮保存进度。','Browser storage is unavailable. Use Export below to keep your progress.')}</div>`:''}<div class="settings-row">${icon('download',23)}<div class="settings-copy"><h3>${t('导出花园存档','Export garden save')}</h3><p>JSON · ${t('包含种植、图鉴、资源和任务进度','Plants, collection, resources and goal progress')}</p></div><button class="secondary-button" data-action="export">${t('导出','Export')}</button></div><div class="settings-row">${icon('upload',23)}<div class="settings-copy"><h3>${t('导入已有存档','Import a garden save')}</h3><p>${t('会先检查文件，再由你确认恢复','The file is checked before you confirm restore')}</p></div><button class="secondary-button" data-action="import">${t('导入','Import')}</button></div><div class="settings-row">${icon('reset',23)}<div class="settings-copy"><h3>${t('从新的花园开始','Start a fresh garden')}</h3><p>${t('会清除当前本地进度','Clears current local progress')}</p></div><button class="quiet-button danger-button" data-action="reset-confirm">${t('重置','Reset')}</button></div><div class="modal-note">${t('这是单人花园，没有账号、云存档或全服排行榜。无需连接钱包，也不发起链上交易。','This is a single-player garden without accounts, cloud saves or global leaderboards. No wallet connection or blockchain transactions are required.')}</div>`);}
function about(){openModal(t('关于 Squeek Grove','About Squeek Grove'),`<p>${t('一款围绕 Squeektoshi 真实跑轮活动设计的独立社区种植游戏，由沐光打造。','An independent community gardening game designed around Squeektoshi’s real wheel activity, created by Muguang.')}</p><h3>${t('真实数据，实在的作用','Real data with a role to play')}</h3><p>${t('真实跑轮工作量为灌溉蓄能，玩家选择培育哪些地块，把跑轮作物用于专送订单。能量记录展示所用读数。转速来自硬件，区块高度来自已结算记录；花园光影随本地时间变化，也可手动选择。','Real wheel work supplies stored irrigation energy. Choose plots and grow special crops for wheel deliveries. Local records show the readings used. RPM is hardware data; height is settled data. Garden lighting follows local time or your chosen scene.')}</p><p>${t('本作品与 Squeekchain 官方无隶属关系。游戏进度不代表白名单资格、收益或官方审核结果。','This project is not affiliated with the Squeekchain team. Game progress does not represent whitelist eligibility, financial rewards or an official review result.')}</p><div class="modal-links"><a href="https://docs.squeekchain.com/developers/api/" target="_blank" rel="noopener noreferrer">${t('公开 API 文档','Public API docs')} ↗</a><a href="https://squeekchain.com/genesis/code" target="_blank" rel="noopener noreferrer">Genesis Code ↗</a></div>`);}
function seedDetail(id){const s=seedById(id);if(!s)return;openModal(nameOf(s),`<div class="modal-seed-art">${plantArt(s.id,1,140)}</div><div class="modal-stats"><span>${t('成长时间','Growth time')}<strong>${secText(s.duration)}</strong></span><span>${t('种植成本','Seed cost')}<strong>${s.cost}</strong></span><span>${t('普通售价','Regular sale price')}<strong>${s.reward}</strong></span><span>${t('园丁经验','Experience')}<strong>+${s.xp}</strong></span></div><p>${t(`浇水一次可减少 ${Math.round(s.duration*.25)} 秒等待。需要园丁 Lv.${s.level}。`, `Water once to save ${Math.round(s.duration*.25)} seconds. Requires gardener Lv.${s.level}.`)}</p><p>${t(`已经收获 ${state.collection[id]} 株。`,`You have harvested ${state.collection[id]} of these plants.`)}</p><div class="modal-actions"><button class="primary-button" data-action="plant-from-journal" data-seed="${id}" ${levelOf(state.xp)<s.level?'disabled':''}>${t('带去花园种植','Take to my garden')} ${icon('arrow',14)}</button></div>`);}
function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function postcardSVG(){const crops=state.plots.map((p,i)=>{const x=100+(i%3)*130,y=210+Math.floor(i/3)*92;return `<g transform="translate(${x} ${y})"><ellipse cx="50" cy="70" rx="54" ry="25" fill="${p.unlocked?'#b99c75':'#b7c797'}" stroke="${p.unlocked?'#d2bb8e':'#a8bb87'}" stroke-width="5"/>${p.plant?plantArt(p.plant.seed,progressOf(p.plant,Date.now()),85):''}</g>`;}).join('');return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="660" viewBox="0 0 1000 660"><rect width="1000" height="660" rx="25" fill="#f6f4e9"/><rect x="30" y="30" width="940" height="600" rx="18" fill="#e5ebd8"/><circle cx="820" cy="160" r="55" fill="#f5e9b8"/><path d="M30 280Q240 150 480 300T970 280v330H30" fill="#c8d6a7"/><text x="75" y="110" font-family="Georgia,serif" font-size="47" fill="#365b42">Squeek Grove</text><text x="78" y="146" font-family="sans-serif" font-size="16" letter-spacing="3" fill="#7f936c">A LITTLE WORLD, GROWING.</text>${crops}<g transform="translate(665 300) scale(1.25)">${hamster().replace('<svg','<svg width="160" height="150"')}</g><text x="665" y="270" font-family="sans-serif" font-size="21" fill="#54734a">GARDENER LV. ${levelOf(state.xp)}</text><text x="665" y="300" font-family="sans-serif" font-size="15" fill="#7f936c">${state.stats.harvested} harvests · ${Object.values(state.collection).filter(v=>v>0).length}/4 species</text><path d="M75 555h850" stroke="#a8bc8c"/><text x="75" y="592" font-family="sans-serif" font-size="14" fill="#5f7954">Grown with care by Muguang · Powered by Squeektoshi’s wheel</text><text x="925" y="592" text-anchor="end" font-family="sans-serif" font-size="12" fill="#7a8e69">${new Date().toISOString().slice(0,10)}</text></svg>`;}
function share(){if(postcardURL)URL.revokeObjectURL(postcardURL);postcardURL=URL.createObjectURL(new Blob([postcardSVG()],{type:'image/svg+xml;charset=utf-8'}));openModal(t('寄出一张花园明信片','A postcard from your garden'),`<img class="postcard-preview" src="${postcardURL}" alt="${t('当前花园的收获与植物快照','A snapshot of your plants and harvests')}"><p>${t('留住这一刻的小花园。图片仅包含游戏画面与成长数据。','Keep a little moment from your garden. The image only includes game artwork and progress.')}</p><div class="modal-actions"><button class="primary-button" data-action="download-card">${icon('download',15)}${t('保存 PNG 图片','Save PNG')}</button><button class="secondary-button" data-action="copy-link">${icon('share',14)}${t('复制花园链接','Copy garden link')}</button></div><input class="copy-url" aria-label="${t('花园链接','Garden URL')}" readonly value="${escape(location.origin+location.pathname)}"><p style="font-size:10px">${t('链接打开的是游戏；你的个人进度只保存在本机。','The link opens the game; your personal progress stays on this device.')}</p>`);}
async function downloadCard(){try{const img=new Image();img.src=postcardURL;await img.decode();const canvas=document.createElement('canvas');canvas.width=2000;canvas.height=1320;canvas.getContext('2d').drawImage(img,0,0,2000,1320);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('export');download(blob,'squeek-grove-postcard.png');toast(t('明信片已生成，正在下载。','Your postcard is ready to download.'));}catch(e){download(new Blob([postcardSVG()],{type:'image/svg+xml'}),'squeek-grove-postcard.svg');toast(t('已改为下载 SVG 矢量明信片。','Downloaded a vector SVG postcard instead.'));}}
async function handleAction(event){const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,index=Number(el.dataset.index);if(a==='nav'){event.preventDefault();life.clearEffects();view=el.dataset.view;render();return;}
 if(a==='scene-mode'){life.setMode(el.dataset.mode);return;}
 if(a==='scene-motion'){life.toggleMotion();return;}
 if(a==='pet-hamster'){life.pet();return;}
 if(a==='plot'){const p=state.plots[index];selectedPlot=index;if(p.unlocked&&p.plant&&progressOf(p.plant,Date.now())>=1)perform({type:'harvest',index});else if(p.unlocked&&!p.plant)perform({type:'plant',index,seed:selectedSeed});else{renderPlots();renderFocus();}return;}
 if(a==='seed'){const s=seedById(el.dataset.seed);if(levelOf(state.xp)<s.level){seedDetail(s.id);return;}selectedSeed=s.id;render();toast(t(`选中${s.zh}，点击空地播种。`,`${s.en} selected. Tap an empty plot.`));return;}
 if(['water','harvest','unlock','irrigate'].includes(a)){perform({type:a,index});return;}
 if(a==='irrigate-selected'){perform({type:'irrigate',index:selectedPlot});return;}
 if(a==='claim'){perform({type:'claim',id:el.dataset.id});return;}
 if(a==='decor'){perform({type:'decor',id:el.dataset.id});return;}
 if(a==='harvest-all'){const lv=levelOf(state.xp),flights=[];let count=0,xp=0;for(let i=0;i<9;i++){if(state.plots[i].plant&&progressOf(state.plots[i].plant,Date.now())>=1){const origin=life.capture(i),seed=state.plots[i].plant.seed,r=applyAction(state,{type:'harvest',index:i});if(r.ok){count++;xp+=r.xp;flights.push({origin,seed,index:i});}}}if(count){sounds.play(levelOf(state.xp)>lv?'level':'harvest');afterAction();life.react('harvest');flights.slice(0,4).forEach((f,i)=>life.effect('harvest',f.index,f.origin,f.seed,i*75));toast(t(`${count} 份收成已入仓 · +${xp} 经验。去仓库安排出售或交单。`,`${count} crops stored · +${xp} XP. Sell or deliver them from your warehouse.`));}else toast(t('还没有成熟的植物，可以先安排灌溉。','No ripe crops yet. Plan your irrigation first.'));return;}
 if(a==='sell'){perform({type:'sell',seed:el.dataset.seed,quality:el.dataset.quality,quantity:1});return;}
 if(a==='energy-log'){energyLog();return;}
 if(a==='accept-order-preview'){acceptOrderPreview(el.dataset.id);return;}
 if(a==='accept-order-apply'){if(perform({type:'accept-order',id:el.dataset.id})){modal.close();view='garden';render();}return;}
 if(a==='deliver-preview'){deliveryPreview();return;}
 if(a==='deliver-apply'){perform({type:'deliver',sequence:Number(el.dataset.sequence)});modal.close();return;}
 if(a==='cancel-order-confirm'){if(!state.activeOrder)return;openModal(t('取消这份订单？','Cancel this order?'),`<p>${t('已种下的植物和仓库库存都会保留，取消后可以选择另一份订单。','Plants and warehouse stock are kept. You can choose another order afterwards.')}</p><div class="modal-actions"><button class="secondary-button" data-action="close">${t('继续这单','Keep this order')}</button><button class="primary-button" data-action="cancel-order-apply" data-sequence="${state.activeOrder.sequence}">${t('确认取消','Cancel order')}</button></div>`);return;}
 if(a==='cancel-order-apply'){perform({type:'cancel-order',sequence:Number(el.dataset.sequence)});modal.close();return;}
 if(a==='language'){lang=lang==='zh'?'en':'zh';try{localStorage.setItem(LANG,lang);}catch(e){}render();return;}
 if(a==='music-toggle'){if(!await music.toggle())toast(t('音乐暂时未能播放，请再点一次试试。','Music could not start. Please try again.'));return;}
 if(a==='sound-toggle'){sounds.toggle();return;}
 if(a==='sound-preview'){sounds.play('harvest');return;}
 if(a==='help'){help();return;}if(a==='settings'){settings();return;}if(a==='about'){about();return;}if(a==='close'){modal.close();return;}
 if(a==='reconnect'){lastSample=null;poll();return;}if(a==='seed-detail'){seedDetail(el.dataset.seed);return;}
 if(a==='plant-from-journal'){selectedSeed=el.dataset.seed;view='garden';modal.close();render();toast(t('已选好种子，点击空地播种。','Seed selected. Tap an empty plot to plant.'));return;}
 if(a==='export'){tick(state);download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'squeek-grove-save.json');toast(t('存档已导出，请妥善保存。','Garden save exported. Keep it somewhere safe.'));return;}
 if(a==='import'){document.querySelector('#import-file').click();return;}
 if(a==='import-apply'){if(!pendingImport)return;state=pendingImport;pendingImport=null;lastSample=null;workRemainder=0;selectedPlot=null;save();modal.close();render();toast(t('花园已恢复。欢迎回来。','Garden restored. Welcome back.'));return;}
 if(a==='reset-confirm'){openModal(t('重新开始这座花园？','Start a new garden?'),`<p>${t('当前种植、资源、图鉴和任务进度都会清除。建议先导出一份存档。','Your plants, resources, journal and goals will be cleared. Export a save first if you would like to keep them.')}</p><div class="modal-actions"><button class="secondary-button" data-action="export">${t('先导出存档','Export first')}</button><button class="primary-button" data-action="reset-apply">${t('确认重新开始','Start again')}</button></div>`);return;}
 if(a==='reset-apply'){state=freshState();selectedPlot=null;selectedSeed='carrot';view='garden';lastSample=null;workRemainder=0;save();modal.close();render();toast(t('新的一天，新的一座小花园。','A fresh little garden is waiting for you.'));return;}
 if(a==='share'){share();return;}if(a==='download-card'){await downloadCard();return;}
 if(a==='copy-link'){try{await navigator.clipboard.writeText(location.origin+location.pathname);toast(t('花园链接已复制。','Garden link copied.'));}catch(e){const field=modal.querySelector('.copy-url');field.focus();field.select();toast(t('请复制下方已选中的链接。','Copy the selected link below.'));}return;}
}
app.addEventListener('click',handleAction);modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}else handleAction(e);});
modal.addEventListener('input',event=>{if(event.target.id==='music-volume')music.setVolume(event.target.value);else if(event.target.id==='sound-volume')sounds.setVolume(event.target.value);});
modal.addEventListener('close',()=>{pendingImport=null;});
document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>100000)throw Error('too_large');pendingImport=validateSave(JSON.parse(await file.text()));openModal(t('恢复这份花园存档？','Restore this garden save?'),`<p>${t(`存档包含：园丁 Lv.${levelOf(pendingImport.xp)}、${pendingImport.stats.harvested} 次收获、${pendingImport.coins} 枚种子币。`,`This save contains gardener Lv.${levelOf(pendingImport.xp)}, ${pendingImport.stats.harvested} harvests and ${pendingImport.coins} seed coins.`)}</p><div class="modal-note">${t('恢复会覆盖当前浏览器的花园进度。','Restoring replaces the current garden in this browser.')}</div><div class="modal-actions"><button class="secondary-button" data-action="close">${t('取消','Cancel')}</button><button class="primary-button" data-action="import-apply">${t('确认恢复','Restore garden')}</button></div>`);}catch(error){pendingImport=null;toast(t('存档格式不正确或版本不支持，原有花园未改变。','Invalid or unsupported save. Your current garden is unchanged.'));}});
window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue){try{state=validateSave(JSON.parse(e.newValue));render();toast(t('已同步另一个页面的最新进度。','Progress updated from another tab.'));}catch(e){}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else{tick(state);render();lastSample=null;workRemainder=0;poll();}});
window.addEventListener('pagehide',save);
render();save();music.start();poll();
setInterval(()=>{updateStats();if(view==='garden'){renderPlots();renderFocus();renderLive();life.update();}},1000);
saveTimer=setInterval(save,10000);
if(loadWarning)setTimeout(()=>toast(t('没有读到有效存档，已创建新花园。可在设置里导入备份。','No valid save found. A new garden is ready; you can import a backup in settings.')),700);

if(migrated&&!loadWarning)setTimeout(()=>toast(t('花园已升级。旧版金币、等级和植物都保留，收获现在会先入仓。','Garden upgraded. Coins, levels and plants are preserved. New harvests now enter storage.')),1000);
function acceptOrderPreview(id){
 const order=orderById(id);if(!order)return;
 const needEnergy=order.quality==='charged'?Object.entries(order.needs).reduce((n,[seed,count])=>n+Math.max(0,count-state.inventory[seed].charged)*IRRIGATION_COST,0):0;
 openModal(nameOf(order),`<p>${t('确认后开始计时，关闭页面也会继续计时。交付前可以查看具体扣除明细。','The timer starts after confirmation and continues when the page is closed. Review the exact crops before delivering.')}</p>${orderNeeds(state,order,lang)}<div class="modal-stats"><span>${t('交付时限','Time limit')}<strong>${order.duration/60} ${t('分钟','minutes')}</strong></span><span>${t('种子币报酬','Seed coins')}<strong>${order.reward}</strong></span><span>${t('经验','Experience')}<strong>+${order.xp}</strong></span></div>${needEnergy?`<div class="modal-note">${t(`还缺少的跑轮作物至少需要 ${needEnergy} 点灌溉能量。当前储能 ${state.energy} 点；可以先储能再接单。`,`Your missing wheel-grown crops need at least ${needEnergy} irrigation energy. You have ${state.energy}; you can bank more before accepting.`)}</div>`:''}<div class="modal-actions"><button class="secondary-button" data-action="close">${t('再安排一下','Plan a little more')}</button><button class="primary-button" data-action="accept-order-apply" data-id="${order.id}">${t('确认接单并计时','Accept and start timer')}</button></div>`);
}
function deliveryPreview(){
 tick(state);if(!state.activeOrder){toast(t('订单已经结束，请查看最新状态。','This order has ended. Check the current status.'));render();return;}
 const plan=deliveryPlan(state),order=orderById(state.activeOrder.id);if(!plan.ready){toast(t('收成还没准备齐，继续安排种植吧。','The harvest is not ready yet. Keep growing.'));return;}
 openModal(t('核对这份交付','Review your delivery'),`<p>${t('确认后扣除以下库存，并发放订单奖励。','Confirm to spend the following crops and receive the order reward.')}</p><div class="delivery-list">${plan.items.map(i=>`<div><b>${nameOf(seedById(i.id))}</b><span>${i.normal?t(`普通 ×${i.normal}`,`Regular ×${i.normal}`):''}${i.normal&&i.charged?' + ':''}${i.charged?t(`跑轮作物 ×${i.charged}`,`Wheel-grown ×${i.charged}`):''}</span></div>`).join('')}</div><div class="modal-note">${nameOf(order)} · +${order.reward} ${t('种子币','seed coins')} · +${order.xp} XP</div><div class="modal-actions"><button class="secondary-button" data-action="close">${t('暂不交付','Keep growing')}</button><button class="primary-button" data-action="deliver-apply" data-sequence="${state.activeOrder.sequence}">${t('确认交付','Confirm delivery')}</button></div>`);
}
function energyLog(){
 openModal(t('这份能量，从跑轮来','Energy from the real wheel'),`<div class="energy-summary"><span>${t('当前储存','Stored now')}<b>${state.energy}/100</b></span><span>${t('本版累计积攒','Earned in v2')}<b>${state.stats.energyEarned}</b></span><span>${t('本版灌溉消耗','Spent in v2')}<b>${state.stats.energySpent}</b></span></div><p>${t('页面开启时，连续的新鲜硬件读数会积攒能量。每 5 个新增工作单位兑换 1 点，单次最多计入 500 个工作单位，储能上限 100。','Consecutive fresh hardware readings earn energy while the page is open: one energy per five new work units, up to 500 units per sample and a 100-energy storage cap.')}</p>${state.energyLog.length?`<div class="energy-records">${state.energyLog.map(e=>`<div><span>${new Date(e.at).toLocaleTimeString(lang==='zh'?'zh-CN':'en-US')}</span><b>+${e.added} ${t('能量','energy')}</b><small>${t('计数','Counter')} ${escape(e.fromWork)} → ${escape(e.toWork)} · ${t('计入','Counted')} ${e.units}</small><small>${t('已结算高度','Settled height')} ${escape(e.height??'—')}</small></div>`).join('')}</div>`:`<div class="modal-note">${t('还没有新增跑轮工作记录。首次连接只建立基线，等仓鼠跑起来后再积攒；普通订单现在就能玩。','No new wheel work recorded yet. Initial connection only sets a baseline; standard orders are playable now.')}</div>`}<p class="order-small">${t('这是引用官方 API 读数的本地游戏记录，存档可编辑。它不证明链上交易、真实身份或官方奖励资格。断线、数据过期和非硬件读数不会补发能量。','These are editable local game records based on the official API, not proof of onchain transactions, identity or official reward eligibility. Disconnections, stale and non-hardware readings do not award catch-up energy.')}</p><div class="modal-links"><a href="${API}" target="_blank" rel="noopener noreferrer">${t('查看官方实时接口','View the official API')} ↗</a></div>`);
}
